#!/usr/bin/env python3
"""Compile and execute the real revision-2/revision-3 layout, route and geometry probe. NOT UNITY."""
import measure_city_rebirth_04o as base
base.CODE=r'''
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using System.Text;using System.Text.Json;using NeonSyndicate;using UnityEngine;
public sealed class Input {public string Version;public List<VenueDefinition04C> Venues=new List<VenueDefinition04C>();}
public static class Probe {
static float Length(IList<Vector3> path){float value=0;for(int i=1;i<path.Count;i++)value+=Vector3.Distance(path[i-1],path[i]);return value;}
static float? Route(CityLayout l,Vector3 a,Vector3 b){var path=l.FindWalkRoute04O(a,b);return path.Count==0?(float?)null:Length(path);}
static object P(Vector3 p){return new[]{p.x,p.y,p.z};}
static VenueCatalog04C Catalog(string file){var errors=new List<string>();var input=QuestJson.Read<Input>(File.ReadAllText(file),file,errors,null);if(errors.Count>0)throw new Exception(string.Join(";",errors));return new VenueCatalog04C{Version=input.Version,Venues=input.Venues.ToArray()};}
static object Write(string name,params MeshBuilder[] meshes){var text=new StringBuilder();int offset=0,triangles=0,degenerate=0,normalErrors=0;foreach(var m in meshes){foreach(var v in m.Vertices){if(!MathUtil.IsFinite(v))throw new Exception("nonfinite geometry");text.AppendFormat(System.Globalization.CultureInfo.InvariantCulture,"v {0:R} {1:R} {2:R}\n",v.x,v.y,v.z);}foreach(var list in (List<int>[])typeof(MeshBuilder).GetField("_tris",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(m))for(int i=0;i<list.Count;i+=3){for(int n=0;n<3;n++)if(list[i+n]<0||list[i+n]>=m.VertexCount)throw new Exception("invalid index");var face=Vector3.Cross(m.Vertices[list[i+1]]-m.Vertices[list[i]],m.Vertices[list[i+2]]-m.Vertices[list[i]]);if(face.sqrMagnitude<1e-10f)degenerate++;else if(Vector3.Dot(face.normalized,m.Normals[list[i]])<.98f)normalErrors++;text.AppendLine("f "+(list[i]+1+offset)+" "+(list[i+1]+1+offset)+" "+(list[i+2]+1+offset));triangles++;}offset+=m.VertexCount;}File.WriteAllText(name+".obj",text.ToString());return new{name,vertices=offset,triangles,degenerate,normalErrors};}
public static void Main(string[] args){var cat=Catalog(args[0]);var worlds=new List<object>();var exports=new List<object>();
foreach(int rev in new[]{2,3}){var l=new CityLayout(61724);l.Generate();var venues=InhabitedCityBindings04C.Select(l,cat);if(!l.ApplyProfile04O((CityRevision04O)rev,venues))throw new Exception("profile rejected");var home=l.FindPoi("Veyra Lofts");Vector3 start=home.Position+home.Facing*3.5f;
worlds.Add(new{revision=rev,spawn=P(start),services=venues.Select(v=>new{id=v.Definition.Id,position=P(v.Outside),metres=Route(l,start,v.Outside)}),threshold=new{position=P(l.RealmThreshold04OB),metres=Route(l,start,l.RealmThreshold04OB)},grotto=new{position=P(l.RealmGrotto04OB),metres=Route(l,start,l.RealmGrotto04OB)},challenge=new{position=P(l.RealmChallenge04OC),metres=Route(l,start,l.RealmChallenge04OC)},azure=new{position=P(l.AzureGlade04OC),metres=Route(l,start,l.AzureGlade04OC)},routes=l.RealmRoutes04OB.Select(r=>new{r.Id,r.Width,points=r.Points.Select(p=>P(p)),segments=r.Points.Skip(1).Select((b,i)=>new{clear=l.ClearPassage04O(r.Points[i],b,1.8f),a=P(r.Points[i]),b=P(b)})}),buildings=l.Blocks.SelectMany(b=>b.Lots).SelectMany(t=>t.Buildings).Select(b=>new{b.Seed,b.Height,b.GothicFamily04OB,b.RebirthFamily04O,roof=b.Roof.ToString(),footprint=new[]{b.Footprint.X0,b.Footprint.Z0,b.Footprint.X1,b.Footprint.Z1}}),coverage=l.WildCoverage04OC.Select(r=>new{r.Seed,r.BlockId,r.Identity,r.Disposition,r.BeforeHeight,r.AfterHeight,before=new[]{r.Before.X0,r.Before.Z0,r.Before.X1,r.Before.Z1},after=new[]{r.After.X0,r.After.Z0,r.After.X1,r.After.Z1}}),scenery=l.WildScenery04OC.Select(s=>new{s.Kind,s.Region,s.Seed,position=P(s.Position),size=P(s.Size)}),terrain=l.WildPatches04OC.Select(p=>new{area=new[]{p.Area.X0,p.Area.Z0,p.Area.X1,p.Area.Z1},p.Seed,p.Height,p.Region}),roads=l.Edges.Count,lanes=l.Lanes.Count,walkNodes=l.WalkNodes.Count,walkLinks=l.WalkLinks.Count,externalStructures=l.DesertLots.SelectMany(t=>t.Buildings.Select(b=>new{t.PoiName,t.CustomBuilt,b.Seed,b.Height,footprint=new[]{b.Footprint.X0,b.Footprint.Z0,b.Footprint.X1,b.Footprint.Z1}})),specialSites=l.Sites.Select(site=>new{site.Key,site.Name,site.Radius,position=P(site.Position)}),captureWaypoints=GoldenViews.Build(l).Where(v=>v.Id.StartsWith("04oc_")).Select(v=>new{v.Id,v.Title,position=P(v.Position),lookAt=P(v.LookAt),v.Fov})});
if(rev!=3)continue;
var district=new MeshBuilder(1);foreach(var b in l.RealmBuildings04OB)if(MathUtil.FlatDistance(b.Footprint.Center(0),start)<360)GothicRealmGeometry04OB.Family(district,district,district,b,false);
foreach(var v in venues){var shell=new MeshBuilder(1);GothicRealmGeometry04OB.Venue(shell,shell,shell,v.Width,v.Depth,v.Building.Height,v.Definition.Id,false,v.Building.RoofPad04OB);for(int n=0;n<shell.Vertices.Count;n++){shell.Vertices[n]=InhabitedCityBindings04C.LocalToWorld(v.Origin,v.Yaw,shell.Vertices[n]);shell.Normals[n]=QMath.AY(v.Yaw)*shell.Normals[n];}district.Append(shell);}
exports.Add(Write("04oc-shipping-world-solids",district));
var land=new MeshBuilder(1);foreach(var p in l.WildPatches04OC)if(MathUtil.FlatDistance(p.Area.Center(0),start)<360)GothicRealmGeometry04OB.WildTerrain04OC(land,l,p);exports.Add(Write("04oc-shipping-near-terrain",land));
var forest=new MeshBuilder(1);foreach(var s in l.WildScenery04OC)if(MathUtil.FlatDistance(s.Position,start)<360){if(s.Kind==0)GothicRealmGeometry04OB.WildTree04OC(forest,forest,s,true);else if(s.Kind==1)GothicRealmGeometry04OB.Crystal(forest,s.Position,s.Size,.07f,s.Seed);else GothicRealmGeometry04OB.Rock(forest,s.Position,s.Size,s.Seed);}exports.Add(Write("04oc-shipping-near-forest",forest));
}
Console.WriteLine(JsonSerializer.Serialize(new{scope="Actual compiled source topology and geometry. NOT UNITY, not skyline pixels, travel time, rendered visuals or performance.",worlds,geometry=exports}));}}
'''
if __name__=='__main__':base.main()
